/**
 * Quick fixes for the problems the metamodel constraints and the DSL checks report. They work on the
 * model (semantic modifications), so the editor reformats only the changed parts.
 */
public class RangoModeQuickfixProvider extends DefaultQuickfixProvider {

	@Fix(GamemodeConstraints.ISSUE_NEVER_ENDS)
	public void makeModeEnd(Issue issue, IssueResolutionAcceptor acceptor) {
		acceptor.accept(issue, "Win when all enemies are cleared", "Adds the win condition 'all enemies cleared'.", "win.png",
				(EObject element, IModificationContext context) -> {
					((GameMode) element).getWinConditions().add(GamemodeFactory.eINSTANCE.createCleared());
				});
		acceptor.accept(issue, "Make the waves loop", "Makes the mode endless: its waves start over once cleared.",
				"waves.png", (EObject element, IModificationContext context) -> {
					GameMode mode = (GameMode) element;
					if (mode.getLevels().size() == 1 && mode.getLevels().get(0).getSpawning() instanceof WaveSchedule schedule) {
						schedule.setLoop(true);
					}
				});
	}

	@Fix(GamemodeConstraints.ISSUE_HEALTH_NOT_DECISIVE)
	public void loseOnHealth(Issue issue, IssueResolutionAcceptor acceptor) {
		acceptor.accept(issue, "Lose when health is depleted", "Adds the lose condition 'health depleted'.", "lose.png",
				(EObject element, IModificationContext context) -> {
					((GameMode) element).getLoseConditions().add(0, GamemodeFactory.eINSTANCE.createHealthDepleted());
				});
	}

	/**
	 * Gives every enemy type of the mode that lacks one a drop table: 10 % of the first power-up of the
	 * edition. The tables go where the mode's drops come from: the mode's own tables if it has any,
	 * otherwise the edition's.
	 */
	@Fix(GamemodeConstraints.ISSUE_NO_DROP_TABLE)
	public void addDropTables(Issue issue, IssueResolutionAcceptor acceptor) {
		acceptor.accept(issue, "Add drop tables for the enemies without one",
				"Adds a 10% drop table for each enemy type of the mode that has none, dropping the edition's first power-up.",
				"drops.png", (EObject element, IModificationContext context) -> {
					GameMode mode = (GameMode) element;
					if (!(mode.eContainer() instanceof Edition edition) || edition.getPowerUps().isEmpty()) {
						return;
					}
					List<DropTable> tables = mode.getDrops().isEmpty() ? edition.getDrops() : mode.getDrops();
					for (EnemyType type : mode.getEnemyTypes()) {
						if (GamemodeDerivations.dropTableFor(mode, type) == null) {
							DropTable table = GamemodeFactory.eINSTANCE.createDropTable();
							table.setEnemyType(type);
							table.setChance(10);
							Drop drop = GamemodeFactory.eINSTANCE.createDrop();
							drop.setPowerUp(edition.getPowerUps().get(0));
							table.getEntries().add(drop);
							tables.add(table);
						}
					}
				});
	}

	@Fix(RangoModeValidator.USELESS_DROP_TABLE)
	public void removeDropTable(Issue issue, IssueResolutionAcceptor acceptor) {
		acceptor.accept(issue, "Remove the drop table", "Removes the drop table, which has no effect.", "drops.png",
				(EObject element, IModificationContext context) -> EcoreUtil.remove(element));
	}

	@Fix(GamemodeConstraints.ISSUE_WRONG_ROLE)
	public void swapRole(Issue issue, IssueResolutionAcceptor acceptor) {
		acceptor.accept(issue, "Move to the other list", "Turns a win condition into a lose condition, or the reverse.",
				"mode.png", (EObject element, IModificationContext context) -> {
					EndCondition condition = (EndCondition) element;
					GameMode mode = (GameMode) condition.eContainer();
					if (condition.isWin()) {
						mode.getLoseConditions().add(condition);
					} else {
						mode.getWinConditions().add(condition);
					}
				});
	}

	@Fix(RangoModeValidator.UNUSED)
	public void removeUnused(Issue issue, IssueResolutionAcceptor acceptor) {
		String name = issue.getData() != null && issue.getData().length > 0 ? issue.getData()[0] : "the element";
		acceptor.accept(issue, "Remove " + name, "Removes " + name + " from the edition.", "edition.png",
				(EObject element, IModificationContext context) -> EcoreUtil.remove(element));
	}

	@Fix(RangoModeValidator.NOT_AN_IMAGE)
	public void addPngExtension(Issue issue, IssueResolutionAcceptor acceptor) {
		acceptor.accept(issue, "Add '.png'", "Adds the file extension of the game's images.", null,
				(EObject element, IModificationContext context) -> {
					if (element instanceof EnemyType type) {
						type.setSprite(type.getSprite() + ".png");
					} else if (element instanceof PowerUp powerUp) {
						powerUp.setSprite(powerUp.getSprite() + ".png");
					} else if (element instanceof Material material) {
						material.setSprite(material.getSprite() + ".png");
					}
				});
	}

	@Fix(RangoModeValidator.BACKGROUND_PATH)
	public void useBackgroundName(Issue issue, IssueResolutionAcceptor acceptor) {
		acceptor.accept(issue, "Use the image name only", "Removes the folder and the extension.", "arena.png",
				(EObject element, IModificationContext context) -> {
					Arena arena = (Arena) element;
					String name = arena.getBackground().substring(arena.getBackground().lastIndexOf('/') + 1);
					arena.setBackground(name.toLowerCase().endsWith(".png") ? name.substring(0, name.length() - 4) : name);
				});
	}
}
